function degrees(n, edges) {
  const degree = new Array(n).fill(0);
  for (const [u, v] of edges) {
    degree[u]++;              // the edge touches u...
    degree[v]++;              // ...and v
  }
  return degree;
}

def degrees(n, edges):
    degree = [0] * n
    for u, v in edges:
        degree[u] += 1        # the edge touches u...
        degree[v] += 1        # ...and v
    return degree

int[] degrees(int n, int[][] edges) {
    int[] degree = new int[n];
    for (int[] e : edges) {
        degree[e[0]]++;       // the edge touches u...
        degree[e[1]]++;       // ...and v
    }
    return degree;
}

vector<int> degrees(int n, vector<vector<int>>& edges) {
    vector<int> degree(n, 0);
    for (auto& e : edges) {
        degree[e[0]]++;       // the edge touches u...
        degree[e[1]]++;       // ...and v
    }
    return degree;
}
